def merchant_encounter (player_stats):
    print("The Merchant: Whadya buyin?")
    time.sleep(2)
    if player_stats["rep"]==0:
        print("The Merchant: Yeah we know who you are. Get Out.\n *You Leave Emptyhanded...*")
